    size_t min_len = std::min(last_key->size(), key.size());
    while (shared < min_len && (*last_key)[shared] == key[shared]) {
        shared++;
    }
} else {
    // At restart point, no shared prefix
    shared = 0;
}

// Calculate unshared part
size_t unshared = key.size() - shared;

// Add entry to buffer
// Format: shared_key_len (varint), unshared_key_len (varint), value_size (varint), unshared_key, value

// For simplicity, using fixed-size encoding or just appending
// LevelDB uses varint encoding, but for this implementation I'll use direct encoding

// Actually, looking at the function signature, it seems like we need to handle this carefully

// Let me reconsider:
// - buffer: where we store the data

// - last_key: previous key (for computing shared prefix)
// - key: current key
// - value: value to store
// - restart_interval: interval for restart points
// - counter: counts entries, when it reaches restart_interval, we add a restart point
// - restarts: vector of offsets where restart points are

// The typical format for each entry in a restart block:
// [shared_key_len (varint32)] [unshared_key_len (varint32)] [value_len (varint32)] [unshared_key (bytes)] [value (bytes)]

// When counter reaches restart_interval, we reset counter to 0 and add current buffer size to restarts

// Implementation:
size_t shared = 0;
if (*counter > 0 && !last_key->empty()) {
    size_t min_len = std::min(last_key->size(), key.size());
    while (shared < min_len && (*last_key)[shared] == key[shared]) {
        shared++;
    }
}

size_t unshared = key.size() - shared;

// Append the entry components to buffer
buffer->append(reinterpret_cast<const char*>(&shared), sizeof(shared));
buffer->append(reinterpret_cast<const char*>(&unshared), sizeof(unshared));
buffer->append(reinterpret_cast<const char*>(&value.size()), sizeof(value.size()));
buffer->append(key.data() + shared, unshared);
buffer->append(value.data(), value.size());

// Update counter and handle restart points
(*counter)++;
if (*counter >= restart_interval) {
    restarts->push_back(buffer->size());
    *counter = 0;
}

// Update last_key
*last_key = key.ToString();

